namespace ghidra.file.formats.cramfs;

using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.app.util.opinion;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.lang;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util.exception;
using ghidra.util.task;

public class CramFsAnalyzer : AbstractAnalyzer {
	// Seen offsets plus the count of how many times seen. Should only be 1
	// for each file inode, if 2 inodes share data space and have same contents.

	public CramFsAnalyzer() : base("CramFS Analyzer", "Annotates CramFS binaries", AnalyzerType.BYTE_ANALYZER)
    {
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return true;
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		try {
			if (!BinaryLoader.BINARY_NAME.equals(program.getExecutableFormat())) {
				return false;
			}
			Language language = program.getLanguage();
			if (language.getProcessor() == Processor.findOrPossiblyCreateProcessor("DATA") &&
				!language.isBigEndian()) {
				return false;
			}
			int magic = program.getMemory().getInt(program.getMinAddress());
			return magic == CramFsConstants.MAGIC;
		}
		catch (MemoryAccessException e) {
			//Ignore
		}
		return false;
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		Address minAddress = program.getMinAddress();
		bool isLE = !program.getLanguage().isBigEndian();

		try
{
    using (ByteProvider provider = new MemoryByteProvider(program.getMemory(), minAddress))
    {

			BinaryReader reader = new BinaryReader(provider, isLE);
			CramFsSuper cramFsSuper = new CramFsSuper(reader);
			DataType dataType = cramFsSuper.toDataType();
			program.getListing().createData(minAddress, dataType);
			program.getListing()
					.setComment(minAddress, CommentType.PLATE, cramFsSuper.getRoot().toString());
			int offset = cramFsSuper.getRoot().getOffsetAdjusted();

			for (int i = 0; i < cramFsSuper.getFsid().getFiles() - 1; i++) {

				monitor.checkCancelled();
				reader.setPointerIndex(offset);
				Address inodeAddress = minAddress.add(offset);
				CramFsInode newInode = new CramFsInode(reader);

				if (newInode.isFile()) {
					Address inodeDataAddress = minAddress.add(newInode.getOffsetAdjusted());
					program.getListing()
							.setComment(inodeDataAddress, CommentType.PLATE,
								newInode.getName() + " Data/Bytes\n");
				}

				DataType inodeDataType = newInode.toDataType();
				program.getListing().createData(inodeAddress, inodeDataType);

				program.getListing()
						.setComment(inodeAddress, CommentType.PLATE,
							newInode.getName() + "\n" + newInode.toString());

				offset += inodeDataType.getLength();
			}
		
    }
}
		catch (Exception e) {
			log.appendException(e);
			return false;
		}

		return true;
	}
}
